def _payload() -> dict:
    import json
    return json.loads(base64.b64decode(PAYLOAD).decode("utf-8"))


GREEN, RED, YELL, DIM, BOLD, END = (
    "\033[92m", "\033[91m", "\033[93m", "\033[2m", "\033[1m", "\033[0m")


def ok(m):    print(f"  {GREEN}OK{END}    {m}")
def warn(m):  print(f"  {YELL}SKIP{END}  {m}")
def fail(m):  print(f"  {RED}FAIL{END}  {m}")
def info(m):  print(f"  {DIM}·{END}     {m}")
def head(m):  print(f"\n{BOLD}{m}{END}")


# ============================================================================
# Patch definitions for backend/app/intent.py
# ============================================================================

FASTER_WHISPER_LOADER = '''def _load_whisper() -> bool:
    """Load faster-whisper (CTranslate2 backend).

    Swapped from openai-whisper, which was never in requirements.txt -- so this
    function failed on every call and I_risk was silently 0.0 for the life of
    the process. Same OpenAI weights, int8 quantised: `small` on this backend
    runs faster than `tiny` did on the original and is markedly better on
    Indian-accented English and Romanised Hindi, which is most of what a vishing
    call in this market actually sounds like.
    """
    global _whisper_model, _whisper_available
    if _whisper_available is not None:
        return _whisper_available
    try:
        from faster_whisper import WhisperModel  # type: ignore[import]
        import os
        model_name = os.environ.get("WHISPER_MODEL", "small")
        log.info("Loading faster-whisper '%s' for intent scoring ...", model_name)
        _whisper_model = WhisperModel(model_name, device="cpu", compute_type="int8")
        _whisper_available = True
        log.info("faster-whisper '%s' loaded -- intent scoring is active.", model_name)
    except Exception as exc:
        log.warning(
            "faster-whisper not available (%s). Intent scoring disabled -- I_risk will be 0.0. "
            "Install with: pip install faster-whisper",
            exc,
        )
        _whisper_available = False
    return _whisper_available
'''

FASTER_WHISPER_TRANSCRIBE = '''            # faster-whisper returns a generator of segments plus an info object.
            audio_copy = audio.astype(np.float32)
            segments, info = _whisper_model.transcribe(
                audio_copy,
                language=None,             # auto-detect
                task="transcribe",
                vad_filter=False,          # our own VAD already gated this window
                condition_on_previous_text=False,
            )
            transcript = " ".join(seg.text for seg in segments).strip()
            result.language_detected = getattr(info, "language", None)
            audio_copy.fill(0)             # zero the copy immediately
'''

FUSION_PATCH = '''    keyword_risk = round(min(1.0, accumulated), 4)

    # --- Pass 3: trained semantic classifier ------------------------------------
    # The two passes above match literal strings. On 50 novel scam phrasings they
    # detect zero, because a scammer who has read a blocklist describes the secret
    # instead of naming it ("jo ankde handset pe blink kar rahe hain"). The model
    # scores paraphrases. Fused with max(): the lexicon is a precision instrument,
    # and averaging its correct 0.6 against a model's 0.2 would discard a true
    # detection. The model only ever adds evidence.
    try:
        from . import intent_model as _im
        fused, diag = _im.combined_score(transcript, keyword_risk)
        result.i_risk = round(fused, 4)
        result.model_diagnostics = diag
    except Exception as _model_err:                       # never break the pipeline
        log.warning("Intent model unavailable on window (%s); keyword-only.", _model_err)
        result.i_risk = keyword_risk
        result.model_diagnostics = {"model_available": False, "error": str(_model_err)}

    result.latency_ms = round((time.perf_counter() - started) * 1000, 2)
    return result'''

DATACLASS_FIELD = '''    whisper_available: bool = False
    model_diagnostics: dict = field(default_factory=dict)'''

# --- Regex false-positive fixes -------------------------------------------------
# max(model, keyword) fusion can raise a score but never lower one, so a keyword
# false positive survives the model entirely. "mere ghar ka pin code chhe lakh
# chaar hai" scores 0.55 from the lexicon and 0.00 from the model, and fuses to
# 0.55. These three patterns cause most of the lexicon's 6% benign false-positive
# rate and have to be fixed at the source.

PIN_PATTERN_FIX = '''    (r"\\b(atm|card|upi|m|debit|credit|banking)\\s*pin\\b", 0.55),'''

POLICE_PATTERN_FIX = '''    (r"\\b(police|cyber\\s*cell)\\b.{0,40}\\b(case|fir|complaint|action|arrest|station bula)", 0.40),'''

DIGIT_HEURISTIC_FIX = '''    # A bare 4-8 digit run is not evidence of anything -- it matches order numbers,
    # PNRs, years, PIN codes, amounts and roll numbers. The digits only carry signal
    # when something nearby frames them as a secret to be read out.
    if _RE_OTP_PATTERN.search(transcript) and re.search(
            r"(otp|code|password|pin|verify|verification|bhej|bata|share|confirm|read|padh|sunao|dictate)",
            transcript, re.IGNORECASE):
        accumulated += 0.20'''

# (description, start_marker, end_marker, consume_end, replacement)
#
# consume_end=False means the end marker is a boundary to stop before and keep
# in place. True means the replacement text already contains it. Getting this
# backwards truncates the marker line and produces an IndentationError, which is
# exactly what the --verify step exists to catch before you ever run the sidecar.
INTENT_PATCHES = [
    ("faster-whisper loader",
     "def _load_whisper() -> bool:",
     "\n\n# ---------------------------------------------------------------------------\n# High-risk phrase lexicon",
     False, FASTER_WHISPER_LOADER),
    ("faster-whisper transcribe call",
     "            import whisper  # type: ignore[import]",
     "            audio_copy.fill(0)         # zero the copy immediately\n",
     True, FASTER_WHISPER_TRANSCRIBE),
    ("model fusion in score()",
     "    result.i_risk = round(min(1.0, accumulated), 4)",
     "    return result",
     True, FUSION_PATCH),
    ("model_diagnostics field on IntentResult",
     "    whisper_available: bool = False",
     None, True, DATACLASS_FIELD),
    ("tighten bare 'pin' pattern (fires on 'shipping pin code')",
     '    ("pin",                  0.55),',
     None, True, PIN_PATTERN_FIX),
    ("tighten bare 'police' pattern (fires on 'police station ke paas')",
     '    ("police",               0.40),',
     None, True, POLICE_PATTERN_FIX),
    ("require code context for bare digit runs",
     "    if _RE_OTP_PATTERN.search(transcript):\n        accumulated += 0.20",
     None, True, DIGIT_HEURISTIC_FIX),
]

REQUIREMENTS_ADD = """
# ---------------------------------------------------------------------------
# Added by voxguard_setup.py
# ---------------------------------------------------------------------------
# faster-whisper replaces openai-whisper, which was referenced by app/intent.py
# but never listed here -- so intent scoring silently returned I_risk = 0.0 on
# every window. CTranslate2 int8 on CPU; `small` here beats the old `tiny`.
faster-whisper>=1.0,<2

# Trained intent classifier (app/intent_model.py). Sentence embeddings are what
# let it score paraphrases the regex lexicon structurally cannot see.
sentence-transformers>=3.0
joblib>=1.3
"""


# ============================================================================
# Steps
# ============================================================================

def find_root(explicit: str | None) -> Path:
    if explicit:
        r = Path(explicit).resolve()
    else:
        r = Path.cwd()
        for cand in (r, *r.parents):
            if (cand / "backend" / "app" / "intent.py").exists():
                r = cand
                break
    if not (r / "backend" / "app" / "intent.py").exists():
        fail(f"not a vox_gaurd repo root: {r}")
        print(f"\n  Run this from the folder that contains backend/ and gateway/,")
        print(f"  or pass it explicitly:  python {Path(sys.argv[0]).name} --root /path/to/vox_gaurd\n")
        sys.exit(1)
    return r


def backup(p: Path, check: bool) -> None:
    if check or not p.exists():
        return
    b = p.with_suffix(p.suffix + ".bak")
    if not b.exists():
        shutil.copy2(p, b)


def step_model(root: Path, check: bool) -> bool:
    dest = root / "backend" / "models" / "intent_model.joblib"
    if check:
        info(f"would write {dest.relative_to(root)} (72 KB)")
        return True
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(_payload()["MODEL_B64"]))
    ok(f"trained model -> {dest.relative_to(root)}")
    return True


def step_intent_model_py(root: Path, check: bool) -> bool:
    dest = root / "backend" / "app" / "intent_model.py"
    if check:
        info(f"would write {dest.relative_to(root)}")
        return True
    backup(dest, check)
    dest.write_text(_payload()["INTENT_MODEL_PY"], encoding="utf-8")
    ok(f"serving module -> {dest.relative_to(root)}")
    return True


def step_blocker_go(root: Path, check: bool) -> bool:
    dest = root / "gateway" / "internal" / "telephony" / "blocker.go"
    if check:
        info(f"would write {dest.relative_to(root)}")
        return True
    dest.parent.mkdir(parents=True, exist_ok=True)
    backup(dest, check)
    dest.write_text(_payload()["BLOCKER_GO"], encoding="utf-8")
    ok(f"call blocker -> {dest.relative_to(root)}")
    return True


def step_probe(root: Path, check: bool) -> bool:
    dest = root / "backend" / "tests" / "data" / "intent_probe.jsonl"
    if check:
        info(f"would write {dest.relative_to(root)}")
        return True
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(_payload()["PROBE_V2"], encoding="utf-8")
    (root / "backend" / "models" / "intent_metrics.json").write_text(_payload()["METRICS"])
    ok(f"eval probe -> {dest.relative_to(root)}")
    return True


def step_intent_py(root: Path, check: bool) -> bool:
    p = root / "backend" / "app" / "intent.py"
    src = p.read_text(encoding="utf-8")
    original = src
    applied, skipped = [], []

    for desc, start, end, consume_end, repl in INTENT_PATCHES:
        if repl.strip() in src:
            skipped.append(f"{desc} (already applied)")
            continue
        if src.count(start) != 1:
            skipped.append(f"{desc} (marker not unique: {src.count(start)} matches)")
            continue
        i = src.index(start)
        if end is None:
            j = i + len(start)
        else:
            k = src.find(end, i)
            if k == -1:
                skipped.append(f"{desc} (end marker not found)")
                continue
            j = k + len(end) if consume_end else k
        src = src[:i] + repl + src[j:]
        applied.append(desc)

    if check:
        for a in applied:
            info(f"would patch: {a}")
        for s in skipped:
            warn(s)
        return True

    if src != original:
        backup(p, check)
        p.write_text(src, encoding="utf-8")
    for a in applied:
        ok(f"intent.py: {a}")
    for s in skipped:
        warn(f"intent.py: {s}")
    return True


def step_requirements(root: Path, check: bool) -> bool:
    p = root / "backend" / "requirements.txt"
    txt = p.read_text(encoding="utf-8")
    if "faster-whisper" in txt:
        warn("requirements.txt already has faster-whisper")
        return True
    if check:
        info("would append faster-whisper, sentence-transformers, joblib")
        return True
    backup(p, check)
    p.write_text(txt.rstrip() + "\n" + REQUIREMENTS_ADD, encoding="utf-8")
    ok("requirements.txt updated")
    return True


CONSENT_TEST_OLD = """    for wav in (ROOT / 'demo_audio').glob('*.wav'):
        if wav.name.startswith(('fixture-', 'tts-')):
            continue"""

CONSENT_TEST_NEW = """    for wav in (ROOT / 'demo_audio').glob('*.wav'):
        if wav.name.startswith(('fixture-', 'tts-')):
            continue
        # The Asterisk adapter streams live call audio through a named pipe in this
        # directory (telephony_adapter/server.py). A FIFO holds no bytes, so it cannot
        # be stored unconsented audio -- and an aborted run leaves one behind, which
        # made this control fail on a file that was never a recording. Path.is_file()
        # is False for a FIFO, so this skips pipes while still catching any regular
        # file that happens to be named live-*.wav.
        if not wav.is_file():
            continue"""


def step_consent_log(root: Path, check: bool) -> bool:
    """Restore docs/CONSENT_LOG.md.

    Commit 8d5e505 ("remove bulky docs directory") deleted it, but
    tests/test_pipeline.py still reads it as the authority for the voice-consent
    invariant -- so that test has been failing with FileNotFoundError ever since.
    The control is worth keeping: it is a test, not a promise in a document, and
    it is the kind of thing an evaluator notices.
    """
    dest = root / "docs" / "CONSENT_LOG.md"
    if dest.exists():
        warn("docs/CONSENT_LOG.md already present")
        return True
    if check:
        info("would restore docs/CONSENT_LOG.md (deleted in 8d5e505, still tested)")
        return True
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(_payload()["CONSENT_LOG_MD"], encoding="utf-8")
    ok("docs/CONSENT_LOG.md restored")
    return True


def step_consent_test(root: Path, check: bool) -> bool:
    """Stop the consent control tripping over the telephony adapter's named pipe."""
    p = root / "backend" / "tests" / "test_pipeline.py"
    src = p.read_text(encoding="utf-8")
    if "if not wav.is_file():" in src:
        warn("consent test already hardened")
        return True
    if src.count(CONSENT_TEST_OLD) != 1:
        warn("consent test: marker not found, skipped")
        return True
    if check:
        info("would harden consent test against FIFOs")
        return True
    backup(p, check)
    p.write_text(src.replace(CONSENT_TEST_OLD, CONSENT_TEST_NEW), encoding="utf-8")
    ok("consent test hardened against leftover FIFOs")
    return True


def step_golden(root: Path, check: bool) -> bool:
    """Bring the scoring golden fixture forward to policy 2.2.0.

    All 91 window vectors plus the policy test were failing: the Go pack moved to
    2.2.0 (intent added as a 4th signal, weights 0.60/0.20/0.20 ->
    0.55/0.15/0.15/0.15) and the fixture still recorded 2.1.0.
    """
    tool = root / "backend" / "tools" / "reweight_golden.py"
    golden = root / "gateway" / "internal" / "scoring" / "testdata" / "golden_windows.json"
    if check:
        info("would install backend/tools/reweight_golden.py and re-derive the fixture")
        return True
    tool.parent.mkdir(parents=True, exist_ok=True)
    tool.write_text(_payload()["REWEIGHT_GOLDEN_PY"], encoding="utf-8")
    ok("backend/tools/reweight_golden.py installed")

    import json as _json
    if '"intent"' in golden.read_text(encoding="utf-8"):
        warn("golden fixture already at 2.2.0")
        return True
    backup(golden, check)
    r = subprocess.run([sys.executable, str(tool)], capture_output=True, text=True, cwd=str(root))
    if r.returncode != 0:
        fail("golden re-derivation failed")
        print(r.stderr)
        return False
    ok(r.stdout.strip().splitlines()[0] if r.stdout.strip() else "golden fixture re-derived")
    return True


def step_verify(root: Path) -> bool:
    """Import the patched module in a subprocess so a syntax error cannot kill us."""
    code = (
        "import ast,sys;"
        "ast.parse(open(r'%s',encoding='utf-8').read());"
        "ast.parse(open(r'%s',encoding='utf-8').read());"
        "print('syntax ok')"
    ) % (root / "backend" / "app" / "intent.py", root / "backend" / "app" / "intent_model.py")
    r = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True)
    if r.returncode == 0:
        ok("patched files parse cleanly")
        return True
    fail("patched intent.py has a syntax error — reverting")
    print(r.stderr)
    return False


def revert(root: Path) -> None:
    head("Reverting")
    n = 0
    for b in list(root.rglob("*.bak")):
        target = b.with_suffix("")
        shutil.copy2(b, target)
        b.unlink()
        ok(f"restored {target.relative_to(root)}")
        n += 1
    for extra in [root / "backend" / "app" / "intent_model.py",
                  root / "gateway" / "internal" / "telephony" / "blocker.go",
                  root / "backend" / "models" / "intent_model.joblib"]:
        if extra.exists() and not extra.with_suffix(extra.suffix + ".bak").exists():
            extra.unlink()
            ok(f"removed {extra.relative_to(root)}")
            n += 1
    print(f"\n  {n} file(s) reverted.\n")


