def main() -> None:
    ap = argparse.ArgumentParser(description="VoxGuard one-file setup")
    ap.add_argument("--root", help="repo root (default: auto-detect)")
    ap.add_argument("--check", action="store_true", help="report only, change nothing")
    ap.add_argument("--revert", action="store_true", help="restore from .bak files")
    a = ap.parse_args()

    root = find_root(a.root)
    print(f"\n{BOLD}VoxGuard setup{END}   repo: {root}")

    if a.revert:
        revert(root)
        return

    mode = "CHECK (no changes)" if a.check else "APPLY"
    print(f"{DIM}mode: {mode}{END}")

    head("1. Trained intent model")
    step_model(root, a.check)
    step_intent_model_py(root, a.check)
    step_probe(root, a.check)

    head("2. Patching backend/app/intent.py")
    step_intent_py(root, a.check)

    head("3. Dependencies")
    step_requirements(root, a.check)

    head("4. Call termination (the missing block path)")
    step_blocker_go(root, a.check)

    head("5. Pre-existing test failures in your repo")
    step_golden(root, a.check)
    step_consent_log(root, a.check)
    step_consent_test(root, a.check)

    if not a.check:
        head("6. Verify")
        if not step_verify(root):
            revert(root)
            sys.exit(1)
        print(NEXT_STEPS)
    else:
        print(f"\n  Nothing was changed. Re-run without --check to apply.\n")


if __name__ == "__main__":
    main()
